  ('94eaf5be-322d-429e-a42a-38ce506bb7a8'::uuid, 'כיסוי לבן לטלית החלאקה, עם רקמה שחורה. מזכרת מטקס החלאקה בגיל שלוש.', '<p>כיסוי לבן לטלית החלאקה, עם רקמה שחורה. הכיסוי שומר על הטלית של הילד מטקס החלאקה, התספורת הראשונה בגיל שלוש, ונשאר אחריו מזכרת. את שם הילד אפשר להוסיף בשדה "הוספת שם אישי" שבעמוד זה, והפרטים מתואמים איתכם לאחר ההזמנה. את המראה והמידות רואים בתמונות המוצר; לשאלות — פנו אלינו לפני ההזמנה.</p>'),
  ('75b30a35-ad8f-416b-970d-3c3ea34ef0d9'::uuid, 'כיסוי לבן לטלית החלאקה, עם רקמה בתכלת. מזכרת מטקס החלאקה בגיל שלוש.', '<p>כיסוי לבן לטלית החלאקה, עם רקמה בתכלת. הכיסוי שומר על הטלית של הילד מטקס החלאקה, התספורת הראשונה בגיל שלוש, ונשאר אחריו מזכרת. את שם הילד אפשר להוסיף בשדה "הוספת שם אישי" שבעמוד זה, והפרטים מתואמים איתכם לאחר ההזמנה. את המראה והמידות רואים בתמונות המוצר; לשאלות — פנו אלינו לפני ההזמנה.</p>')
),
target as (
  select p.id, p.description, p.short_description, c.new_sd, c.new_desc
    from public.products p
    join copy c on c.id = p.id
   where p.description is distinct from c.new_desc
      or p.short_description is distinct from c.new_sd
),
logged as (
  insert into public.product_copy_runs
    (product_id, run_id, description_before, description_after, md5_after,
     short_description_before, short_description_after)
  select id, 'honesty-2026-09-27-chalaka', description, new_desc, md5(new_desc),
         short_description, new_sd
    from target
  returning 1
)
update public.products p
   set description = t.new_desc,
       short_description = t.new_sd
  from target t
 where t.id = p.id;
